#if UNITY_EDITOR
using System;
using System.Linq;
using System.Reflection;
using LastRail.Battle;
using Newtonsoft.Json.Linq;
using NUnit.Framework;
namespace LastRail.Tests.EditMode {
 public sealed class BEnemyAttackAdmissionTests {
  static object Call(object target,string name,params object[] args){var type=target as Type??target.GetType();var m=type.GetMethod(name);Assert.NotNull(m,"Missing opt-in admission boundary: "+name);try{return m.Invoke(target is Type?null:target,args);}catch(TargetInvocationException e){System.Runtime.ExceptionServices.ExceptionDispatchInfo.Capture(e.InnerException).Throw();throw;}}
  static object Policy(string band){var t=typeof(BDirectAttackBasicLoop).Assembly.GetType("LastRail.Battle.BEnemyAttackAdmissionPolicy");Assert.NotNull(t,"Missing approved typed attack admission policy");return Call(t,"ForBand",band);}
  internal static BDirectAttackBasicLoopBinding Multi(int count=5,bool split=false,bool threeTargets=false,long step=10000,Action<JObject> adjust=null,bool ally=false,bool train=false){
   var t=typeof(BDirectAttackBasicLoopTests);var p=(JObject)t.GetMethod("Packet",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{1});p["stepTimeSpanTicks"]=step;var entities=(JArray)p["entities"];var e=(JObject)entities.Single(x=>(string)x["id"]=="enemy");e["basicIntervalMicroseconds"]=1600000;e["maxHp"]=100000;
   var g=(JObject)((JArray)p["geometry"]).Single(x=>(string)x["sourceId"]=="enemy"&&(string)x["targetId"]=="car0");
   var targets=new JArray(new JObject{["sourceId"]="enemy",["targetId"]=train?"train":"car0"});
   for(int n=1;n<count;n++){var c=(JObject)e.DeepClone();c["id"]="enemy"+n;c["definitionId"]="LOCAL_ADMISSION_enemy"+n;entities.Add(c);string target=threeTargets&&n==4?"train":split&&n>=2?"op_mira":"car0";var geom=(JObject)g.DeepClone();geom["sourceId"]=c["id"].DeepClone();geom["targetId"]=target;((JArray)p["geometry"]).Add(geom);targets.Add(new JObject{["sourceId"]=c["id"].DeepClone(),["targetId"]=target});}
   adjust?.Invoke(p);if(ally)targets.Add(new JObject{["sourceId"]="op_mira",["targetId"]="enemy"});var input=(BDirectAttackInput)t.GetMethod("Input",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{p});var defs=(BCarriageBuffDefinitions)t.GetMethod("Defs",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,null);var bp=(JObject)t.GetMethod("BindingPacket",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{input,"BCB01",5,"ENEMY"});
   for(int n=1;n<count;n++)((JArray)bp["targetCategories"]).Add(new JObject{["targetId"]="enemy"+n,["category"]="ENEMY"});var composition=new BDirectAttackBuffBinding(input,defs,bp,BDirectAttackInput.Digest(bp));var route=new JObject{["version"]=BDirectAttackBasicLoopBinding.Version,["provenance"]="BOUNDED_LOCAL_NOT_FULL_RUN",["compositionHash"]=composition.OriginalHash,["targets"]=targets};return new BDirectAttackBasicLoopBinding(composition,route,BDirectAttackInput.Digest(route));
  }
  internal static JObject Timing(BDirectAttackBasicLoopBinding b)=>new JObject{["version"]="unity.combat-b.enemy-basic-timing-local.v1",["provenance"]="EXPLICIT_LOCAL_TIMING_NOT_OPERATING_ENEMY_SOURCE",["bindingHash"]=b.OriginalHash,["timings"]=new JArray(((JArray)b.Capture()["targets"]).Where(r=>(string)r["sourceId"]!="op_mira").Select(r=>new JObject{["sourceId"]=r["sourceId"].DeepClone(),["targetId"]=r["targetId"].DeepClone(),["targetableAt"]=600,["periodMicroseconds"]=1600000,["windupMs"]=500,["recoveryMs"]=300}))};
  static BDirectAttackBasicLoop Fresh(BDirectAttackBasicLoopBinding b=null,string band="EARLY",int capacity=10000){b=b??Multi();var timing=Timing(b);return (BDirectAttackBasicLoop)Call(typeof(BDirectAttackBasicLoop),"CreateAttackAdmissionValidation",b,timing,BDirectAttackInput.Digest(timing),Policy(band),capacity);}
  static void Advance(BDirectAttackBasicLoop s,int ticks,string id)=>s.Advance(id,ticks*10000L,ticks);
  static JArray Events(BDirectAttackBasicLoop s)=>(JArray)s.Capture()["enemyTiming"]["events"];
  static JArray Starts(BDirectAttackBasicLoop s)=>new JArray(Events(s).Where(e=>(string)e["kind"]=="WINDUP").Select(e=>e.DeepClone()));
  static JObject Actor(BDirectAttackBasicLoop s,string id)=>(JObject)((JArray)s.Capture()["enemyTiming"]["actors"]).Single(x=>(string)x["sourceId"]==id);
  static BDirectAttackBasicLoopResult Observe(BDirectAttackBasicLoop s,string eventId,string id,long source=0,long target=0,long field=0,bool eligible=true,long? hazard=null)=>(BDirectAttackBasicLoopResult)Call(s,"RecordEnemyAdmissionState",eventId,id,source,target,field,eligible,hazard??s.Tick);
  static BDirectAttackBasicLoop Restore(BDirectAttackBasicLoop s,BDirectAttackBasicLoopBinding b,string band="EARLY"){var t=Timing(b);return (BDirectAttackBasicLoop)Call(typeof(BDirectAttackBasicLoop),"RestoreAttackAdmissionValidation",s.Capture(),b,t,BDirectAttackInput.Digest(t),Policy(band),10000);}
  [Test] public void SameTargetStartsAreSeparatedAndOnlyTwoSlotsCanParticipate(){var s=Fresh();Advance(s,3300,"run");var starts=Events(s).Where(e=>(string)e["kind"]=="WINDUP").ToArray();CollectionAssert.AreEqual(new long[]{1700,2300,3300},starts.Select(e=>(long)e["tick"]));CollectionAssert.AreEqual(new[]{"enemy","enemy1","enemy2"},starts.Select(e=>(string)e["sourceId"]));Assert.AreEqual(3,starts.Length);}
  [Test] public void TargetBlockedOldestDoesNotStarveAnotherEligibleTarget(){var s=Fresh(Multi(split:true));Advance(s,1700,"start");CollectionAssert.AreEqual(new[]{"enemy","enemy2"},Events(s).Where(e=>(string)e["kind"]=="WINDUP").Select(e=>(string)e["sourceId"]));}
  [TestCase("EARLY",3)][TestCase("MIDDLE",4)][TestCase("LATE",5)] public void SharedGlobalSlotsIncludeAllAllowedTargetKinds(string band,int slots){var s=Fresh(Multi(split:true,threeTargets:true),band);Advance(s,2300,"run");Assert.AreEqual(slots,Starts(s).Count);Assert.AreEqual(slots,((JArray)s.Capture()["enemyTiming"]["admission"]["leases"]).Count);}
  [Test] public void DelayedAdmissionSchedulesActualWindupAndDoesNotFlushOldImpacts(){var s=Fresh();var r=s.Advance("run",38000000,3800);CollectionAssert.AreEqual(new long[]{2200,2800,3800},r.Hits.Select(h=>h.Attack.Tick));CollectionAssert.AreEqual(new[]{"enemy","enemy1","enemy2"},r.Hits.Select(h=>h.Attack.SourceId));}
  [Test] public void CancelDoesNotRefundTargetGapOrOriginalSlotBudget(){var s=Fresh(Multi(2));Advance(s,1700,"start");Observe(s,"cancel","enemy",eligible:false);Observe(s,"return","enemy",source:1);Advance(s,599,"before-gap");Assert.AreEqual(1,Starts(s).Count);Advance(s,1,"gap");Assert.AreEqual("enemy1",(string)Starts(s)[1]["sourceId"]);Observe(s,"hide-second","enemy1",eligible:false);Advance(s,999,"before-reuse");Assert.AreEqual(2,Starts(s).Count);Advance(s,1,"reuse");Assert.AreEqual(3300,s.Tick);Assert.AreEqual("enemy",(string)Starts(s)[2]["sourceId"]);}
  [Test] public void TargetGenerationChangeInvalidatesEveryOldTargetReservation(){var s=Fresh(Multi(2));Advance(s,2300,"two");Observe(s,"target-replaced","enemy",target:1);Assert.AreEqual("IDLE",(string)Actor(s,"enemy1")["phase"]);var r=s.Advance("old-impact",5000000,500);Assert.AreEqual(0,r.Hits.Count);var lives=(JArray)s.Capture()["enemyTiming"]["admission"]["lives"];Assert.IsTrue(lives.All(x=>(long)x["targetGeneration"]==1));}
  [Test] public void BattlefieldGenerationChangeInvalidatesOtherTargetsToo(){var s=Fresh(Multi(3,true));Advance(s,1700,"start");Observe(s,"field","enemy",field:1);Assert.AreEqual("IDLE",(string)Actor(s,"enemy2")["phase"]);Assert.IsTrue(((JArray)s.Capture()["enemyTiming"]["admission"]["lives"]).All(x=>(long)x["battlefieldGeneration"]==1));}
  [Test] public void RemainingHazardKeepsSlotAfterRecoveryAndCancellation(){var s=Fresh(Multi(2));Advance(s,1700,"start");Observe(s,"hazard","enemy",hazard:6000);Observe(s,"cancel","enemy",eligible:false);Observe(s,"cancel-second","enemy1",eligible:false);Observe(s,"return","enemy",source:1);Advance(s,4299,"before-hazard-end");Assert.AreEqual(1,Starts(s).Count);Advance(s,1,"hazard-end");Assert.AreEqual("enemy",(string)Starts(s)[1]["sourceId"]);Assert.AreEqual(6000,(long)Starts(s)[1]["tick"]);}
  [Test] public void LongerOccupationKeepsBudgetUntilRecoveryEndAndFullNextPeriod(){var s=Fresh(Multi(1));Advance(s,1700,"start");s.RecordEnemyRecoveryEnd("occupy","enemy",5000);Advance(s,4399,"before-new-windup");Assert.AreEqual(1,Starts(s).Count);Advance(s,1,"new-windup");Assert.AreEqual(6100,(long)Starts(s)[1]["tick"]);}
  [TestCase(1700)][TestCase(2200)][TestCase(2300)][TestCase(3300)] public void RestorePreservesWaitingLeasesGenerationClockAndLaterReceipts(int tick){var b=Multi();var a=Fresh(b);Advance(a,tick,"boundary");Observe(a,"life","enemy",hazard:6000);var c=Restore(a,b);Assert.IsTrue(JToken.DeepEquals(a.Capture(),c.Capture()));Advance(a,4000,"tail");Advance(c,4000,"tail");Assert.IsTrue(JToken.DeepEquals(a.Capture(),c.Capture()));}
  [Test] public void PauseSpeedDebtAndSplitAdvancesHaveSameAdmissionHistory(){var b=Multi();var a=Fresh(b);var c=Fresh(b);foreach(var s in new[]{a,c}){s.SetSpeed("speed",3);s.Advance("odd",1,0);s.SetPaused("pause",true);Advance(s,500,"paused");Assert.AreEqual(0,Starts(s).Count);s.SetPaused("resume",false);}a.Advance("whole",30000000,4500);for(int n=0;n<30;n++)c.Advance("part"+n,1000000,150);Assert.IsTrue(JToken.DeepEquals(a.Capture()["enemyTiming"],c.Capture()["enemyTiming"]));Assert.AreEqual(a.Hp("car0"),c.Hp("car0"));}
  [Test] public void DuplicateStateIsIdempotentAndConflictLeavesAllOwnersUntouched(){var s=Fresh();Advance(s,1700,"start");var r=Observe(s,"cancel","enemy",eligible:false);var before=s.Capture();Assert.AreSame(r,Observe(s,"cancel","enemy",eligible:false));Assert.Throws<ArgumentException>(()=>Observe(s,"cancel","enemy",source:1,eligible:false));Assert.IsTrue(JToken.DeepEquals(before,s.Capture()));}
  [Test] public void FailedLifetimeOrNativeJournalDoesNotPublishMutatedAdmission(){var s=Fresh(Multi(1),capacity:2);s.SetPaused("pause",true);var before=s.Capture();Assert.Throws<InvalidOperationException>(()=>Observe(s,"overflow","enemy",source:1,eligible:false));Assert.IsTrue(JToken.DeepEquals(before,s.Capture()));var other=Fresh();Observe(other,"generation","enemy",source:1);var unchanged=other.Capture();Assert.Throws<ArgumentException>(()=>Observe(other,"stale","enemy",source:0));Assert.Throws<ArgumentException>(()=>Observe(other,"overflow","enemy",source:9007199254740992));Assert.IsTrue(JToken.DeepEquals(unchanged,other.Capture()));}
  [TestCase("leases")][TestCase("targetNext")][TestCase("lives")] public void RestoreRejectsParticipationTampering(string field){var b=Multi();var s=Fresh(b);Advance(s,1700,"start");var bad=s.Capture();bad["enemyTiming"]["admission"][field]=new JObject();var t=Timing(b);Assert.Throws<ArgumentException>(()=>Call(typeof(BDirectAttackBasicLoop),"RestoreAttackAdmissionValidation",bad,b,t,BDirectAttackInput.Digest(t),Policy("EARLY"),10000));Assert.Throws<ArgumentException>(()=>Restore(s,b,"LATE"));}
  [Test] public void CoarseRecoveryBoundaryStartsNextPreparationAtSameTick(){var b=Multi(1,step:10000000);var t=Timing(b);t["timings"][0]["targetableAt"]=0;var s=(BDirectAttackBasicLoop)Call(typeof(BDirectAttackBasicLoop),"CreateAttackAdmissionValidation",b,t,BDirectAttackInput.Digest(t),Policy("EARLY"),10000);s.Advance("first",20000000,2);s.Advance("recovery",10000000,1);Assert.AreEqual("WINDUP",(string)Actor(s,"enemy")["phase"]);s.Advance("second",10000000,1);Assert.AreEqual(2,Events(s).Count(e=>(string)e["kind"]=="IMPACT"));}
  [Test] public void UnsupportedBandRejectedWithoutAnArbitraryNumericPolicy(){Assert.Throws<ArgumentException>(()=>Policy("BOSS"));}
  [Test] public void PartialTimingRosterCannotBypassAdmissionThroughOriginalBasicRoute(){var b=Multi();var t=Timing(b);((JArray)t["timings"]).RemoveAt(4);Assert.Throws<ArgumentException>(()=>Call(typeof(BDirectAttackBasicLoop),"CreateAttackAdmissionValidation",b,t,BDirectAttackInput.Digest(t),Policy("EARLY"),10000));}
  [Test] public void LifetimeCancellationCannotAdvanceOriginalOccupiedNextBoundary(){var s=Fresh(Multi(1));Advance(s,1700,"start");s.RecordEnemyRecoveryEnd("occupy","enemy",5000);Observe(s,"cancel","enemy",eligible:false);Observe(s,"return","enemy",source:1);Advance(s,4399,"before-original");Assert.AreEqual(1,Starts(s).Count);Advance(s,1,"original");Assert.AreEqual(6100,(long)Starts(s)[1]["tick"]);Advance(s,500,"impact");Assert.AreEqual(6600,(long)Events(s).Single(e=>(string)e["kind"]=="IMPACT")["tick"]);}
  [Test] public void LaterShorterOccupationCannotPullExistingOriginalDueBackward(){var s=Fresh(Multi(1));Advance(s,1700,"start");s.RecordEnemyRecoveryEnd("long","enemy",5000);s.RecordEnemyRecoveryEnd("short","enemy",2000);Assert.AreEqual(5000,(long)Actor(s,"enemy")["occupiedUntil"]);Advance(s,4399,"before-original");Assert.AreEqual(1,Starts(s).Count);Advance(s,1,"original");Assert.AreEqual(6100,(long)Starts(s)[1]["tick"]);}
  [Test] public void OriginalOutOfRangeActorDoesNotReserveOrBlockEligibleOtherTarget(){var b=Multi(3,true,adjust:p=>((JArray)p["geometry"]).Single(g=>(string)g["sourceId"]=="enemy"&&(string)g["targetId"]=="car0")["distanceMm"]=1001);var s=Fresh(b);Advance(s,1700,"run");CollectionAssert.AreEqual(new[]{"enemy1","enemy2"},Starts(s).Select(e=>(string)e["sourceId"]));}
  [Test] public void ActualHpDeathInWindupCannotEmitAndKeepsUsedSlotFloor(){var b=Multi(2,adjust:p=>((JArray)p["entities"]).Single(e=>(string)e["id"]=="enemy")["maxHp"]=80,ally:true);var s=Fresh(b);Advance(s,1802,"death");Assert.AreEqual(0,s.Hp("enemy"));Assert.AreEqual(0,(long)Actor(s,"enemy")["reservationSequence"]);Assert.IsTrue(((JArray)s.Capture()["enemyTiming"]["admission"]["leases"]).Any(l=>(string)l["sourceId"]=="enemy"&&(long)l["reuseAt"]==3300));var r=s.Advance("late",10000000,1000);Assert.IsFalse(r.Hits.Any(h=>h.Attack.SourceId=="enemy"));}
  [Test] public void OldestOpportunityWinsBeforeReturningLowerOrdinal(){var s=Fresh(Multi(3));Observe(s,"hide-first","enemy",eligible:false);Advance(s,1700,"first-other");Observe(s,"return-first","enemy");Advance(s,600,"gap");Assert.AreEqual("enemy2",(string)Starts(s)[1]["sourceId"]);}
  [Test] public void ShuffledTimingAndRouteRowsPreserveOriginalEntityOrdinal(){var b=Multi();var r=b.Capture();r["targets"]=new JArray(((JArray)r["targets"]).Reverse().Select(x=>x.DeepClone()));var shuffled=new BDirectAttackBasicLoopBinding(b.Composition,r,BDirectAttackInput.Digest(r));var t=Timing(shuffled);t["timings"]=new JArray(((JArray)t["timings"]).Reverse().Select(x=>x.DeepClone()));var s=(BDirectAttackBasicLoop)Call(typeof(BDirectAttackBasicLoop),"CreateAttackAdmissionValidation",shuffled,t,BDirectAttackInput.Digest(t),Policy("EARLY"),10000);Advance(s,3300,"run");CollectionAssert.AreEqual(new[]{"enemy","enemy1","enemy2"},Starts(s).Select(x=>(string)x["sourceId"]));}
  [Test] public void TerminalFailureClearsOwnedLeasesAndNoLaterDamage(){var b=Multi(1,adjust:p=>((JArray)p["entities"]).Single(e=>(string)e["id"]=="train")["maxHp"]=1,train:true);var s=Fresh(b);Advance(s,2200,"failure");Assert.AreEqual("FAILURE",s.Outcome);Assert.AreEqual(0,((JArray)s.Capture()["enemyTiming"]["admission"]["leases"]).Count);Assert.AreEqual(0,(long)Actor(s,"enemy")["reservationSequence"]);var native=s.Capture()["state"];Advance(s,1000,"late");Assert.IsTrue(JToken.DeepEquals(native,s.Capture()["state"]));}
 }
}
#endif
